def transform(grid):
    h = len(grid)
    w = len(grid[0])
    out = [[0 for _ in range(w)] for _ in range(3)]
    priority = (5, 4, 8, 2)
    for r in range(3):
        for c in range(w):
            for color in priority:
                if any(grid[band * 3 + r][c] == color for band in range(4)):
                    out[r][c] = color
                    break
    return out
